```js
// dedupeCustomers.js

const isBlank = (v) => v == null || String(v).trim() === '';

/** Lowercase, trim, and fold Gmail aliases (dots, +tags, googlemail.com). */
function normalizeEmail(raw) {
  if (isBlank(raw)) return null;
  const s = String(raw).trim().toLowerCase();
  const at = s.lastIndexOf('@');
  if (at < 1 || at === s.length - 1) return null; // not a usable address
  let local = s.slice(0, at);
  let domain = s.slice(at + 1);
  if (domain === 'googlemail.com') domain = 'gmail.com';
  if (domain === 'gmail.com') local = local.split('+')[0].replace(/\./g, '');
  return local ? `${local}@${domain}` : null;
}

/** Digits only; drops 00 international prefix and a leading US/CA "1". */
function normalizePhone(raw) {
  if (isBlank(raw)) return null;
  let d = String(raw).replace(/\D/g, '');
  if (d.startsWith('00')) d = d.slice(2);
  if (d.length === 11 && d.startsWith('1')) d = d.slice(1);
  return d.length >= 7 ? d : null; // too short to be meaningful
}

/** Set of lowercase, accent-free word tokens. */
function nameTokens(raw) {
  if (isBlank(raw)) return new Set();
  return new Set(
    String(raw)
      .normalize('NFKD')
      .replace(/\p{M}+/gu, '')
      .toLowerCase()
      .split(/[^\p{L}\p{N}]+/u)
      .filter(Boolean)
  );
}

/** "Bob Smith" ~ "bob j. smith" ~ "SMITH, Bob"; "Bob Smith" !~ "Alice Smith". */
function namesCompatible(a, b) {
  if (a.size === 0 || b.size === 0) return true; // nothing to contradict
  const [small, large] = a.size <= b.size ? [a, b] : [b, a];
  for (const t of small) if (!large.has(t)) return false;
  return true;
}

/**
 * Remove duplicate customer records ({ name, email, phone, ...extras }).
 *
 * Two records are duplicates when they share a normalized email, or share a
 * normalized phone AND their names don't contradict each other (so a family or
 * office landline doesn't merge different people). Matching is transitive:
 * A~B and B~C puts all three in one group. Name alone is never enough.
 *
 * @param {object[]} records
 * @param {object}  [opts]
 * @param {'first'|'last'} [opts.keep='first']  Which record in a group survives.
 * @param {boolean} [opts.mergeFields=true]  Fill blank fields on the survivor
 *                                           from the other records in its group.
 * @param {boolean} [opts.phoneNeedsName=true] Require compatible names for phone matches.
 * @returns {{ unique: object[], groups: object[][] }}
 *   `unique` keeps first-appearance order and never mutates the input.
 *   `groups` lists only the clusters that contained duplicates (for audit/review).
 */
function dedupeCustomers(records, opts = {}) {
  const { keep = 'first', mergeFields = true, phoneNeedsName = true } = opts;
  if (!Array.isArray(records)) throw new TypeError('records must be an array');

  const n = records.length;
  const parent = Array.from({ length: n }, (_, i) => i);
  const find = (x) => {
    while (parent[x] !== x) {
      parent[x] = parent[parent[x]]; // path halving
      x = parent[x];
    }
    return x;
  };
  const union = (a, b) => {
    const ra = find(a), rb = find(b);
    if (ra !== rb) parent[Math.max(ra, rb)] = Math.min(ra, rb); // root = earliest
  };

  const byEmail = new Map(); // email -> first index
  const byPhone = new Map(); // phone -> [indices]
  const tokens = records.map((r) => nameTokens(r?.name));

  records.forEach((r, i) => {
    if (r == null || typeof r !== 'object') return;

    const email = normalizeEmail(r.email);
    if (email) {
      if (byEmail.has(email)) union(i, byEmail.get(email));
      else byEmail.set(email, i);
    }

    const phone = normalizePhone(r.phone);
    if (phone) {
      const seen = byPhone.get(phone);
      if (seen) {
        for (const j of seen) {
          if (!phoneNeedsName || namesCompatible(tokens[i], tokens[j])) union(i, j);
        }
        seen.push(i);
      } else {
        byPhone.set(phone, [i]);
      }
    }
  });

  const clusters = new Map(); // root -> indices, in input order
  for (let i = 0; i < n; i++) {
    const root = find(i);
    if (!clusters.has(root)) clusters.set(root, []);
    clusters.get(root).push(i);
  }

  const unique = [];
  const groups = [];
  for (const idxs of clusters.values()) {
    const members = idxs.map((i) => records[i]);
    if (members.length > 1) groups.push(members);

    const order = keep === 'last' ? [...members].reverse() : members;
    const survivor = { ...order[0] };
    if (mergeFields) {
      for (const other of order.slice(1)) {
        for (const [k, v] of Object.entries(other ?? {})) {
          if (isBlank(survivor[k]) && !isBlank(v)) survivor[k] = v;
        }
      }
    }
    unique.push(survivor);
  }
  return { unique, groups };
}

module.exports = { dedupeCustomers, normalizeEmail, normalizePhone };
```

Example:

```js
const { unique, groups } = dedupeCustomers([
  { name: 'Bob Smith',     email: 'Bob.Smith+news@gmail.com', phone: '(555) 123-4567' },
  { name: 'Bob J. Smith',  email: 'bobsmith@gmail.com',       phone: '' },
  { name: 'Robert Smith',  email: '',                         phone: '+1 555-123-4567' },
  { name: 'Alice Smith',   email: 'alice@x.com',              phone: '555 123 4567' }, // same landline, different person
]);
// unique.length === 3: the first two merge on email; "Robert Smith" is kept apart.
// "Alice Smith" is kept apart because her name contradicts the others on the shared phone.
```

**Design choices:**
- **Matching:** Records match on a shared email, or a shared phone with non-contradicting names. A phone match without the name guard would merge housemates and coworkers on a shared line.
- **Transitive groups:** Union-find means A~B and B~C land in one group, however far apart they are in the array. It runs in roughly O(n).
- **Normalization:**
  - Emails are case-folded, and Gmail dots and `+tags` are folded.
  - Phones are reduced to digits, with the `00` and US `1` prefixes stripped.
  - Names are accent-stripped and compared by token subset.
- **No name-only matching:** A record with no usable email or phone is never merged, because two "John Smith" entries are usually different people.
- **Merging:** The survivor's blank fields are filled from its duplicates, so no data is lost. The input isn't mutated.
- **Review:** `groups` returns every cluster that was collapsed, so you can audit merges before trusting them.

**Known limits:**
- Nicknames like Bob/Robert aren't treated as the same name.
- Phone handling assumes US/CA numbers by default. For international data, use a library such as `libphonenumber-js` in `normalizePhone`.
- Fuzzy matching, such as typos in emails, is intentionally left out. It needs a human-review step rather than silent merging.

