'use strict';

let parsePhone = null;
try { ({ parsePhoneNumberFromString: parsePhone } = require('libphonenumber-js')); } catch { /* optional */ }

const isBlank = (v) => v == null || String(v).trim() === '';

const normEmail = (v) => (isBlank(v) ? '' : String(v).trim().toLowerCase());

function normPhone(v) {
  if (isBlank(v)) return '';
  const raw = String(v).trim();
  const parsed = parsePhone && parsePhone(raw, 'US'); // assumes US when no country code
  if (parsed && parsed.isValid()) return parsed.number; // E.164
  let digits = raw.replace(/\D/g, '');
  if (digits.length === 11 && digits[0] === '1') digits = digits.slice(1);
  return digits.length >= 7 ? digits : ''; // too short to be a real match key
}

function dedupeCustomers(records) {
  const parent = records.map((_, i) => i);
  const find = (i) => {
    while (parent[i] !== i) { parent[i] = parent[parent[i]]; i = parent[i]; }
    return i;
  };
  const union = (a, b) => {
    const ra = find(a), rb = find(b);
    if (ra !== rb) parent[Math.max(ra, rb)] = Math.min(ra, rb); // root = earliest index
  };

  const seen = new Map(); // "e:<email>" / "p:<phone>" -> first index
  records.forEach((r, i) => {
    const keys = [];
    const e = normEmail(r.email), p = normPhone(r.phone);
    if (e) keys.push('e:' + e);
    if (p) keys.push('p:' + p);
    for (const k of keys) {
      if (seen.has(k)) union(i, seen.get(k)); else seen.set(k, i);
    }
  });

  const groups = new Map(); // root -> member indexes, inserted in first-appearance order
  records.forEach((_, i) => {
    const root = find(i);
    if (!groups.has(root)) groups.set(root, []);
    groups.get(root).push(i);
  });

  const score = (r) => ['name', 'email', 'phone'].filter((f) => !isBlank(r[f])).length;
  return [...groups.values()].map((idxs) => {
    const members = idxs.map((i) => records[i]);
    const best = members.reduce((a, b) => (score(b) > score(a) ? b : a)); // ties keep earliest
    const merged = { ...best };
    for (const m of members) {
      for (const [k, v] of Object.entries(m)) if (isBlank(merged[k]) && !isBlank(v)) merged[k] = v;
    }
    return merged;
  });
}

module.exports = { dedupeCustomers };
```

## `naive.js` (the baseline the tests should reject)

```js
'use strict';
function dedupeCustomers(records) {
  const emails = new Set(), phones = new Set();
  return records.filter((r) => {
    if (emails.has(r.email) || phones.has(r.phone)) return false;
    emails.add(r.email); phones.add(r.phone);
    return true;
  });
}
module.exports = { dedupeCustomers };
```

