'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { dedupeCustomers } = require(process.env.DEDUPE_IMPL || './dedupeCustomers');

test('email case and whitespace variants merge', () => {
  const out = dedupeCustomers([
    { name: 'Priya Nair', email: 'priya.nair@example.com', phone: '' },
    { name: 'Priya Nair', email: '  Priya.Nair@Example.COM ', phone: '' },
  ]);
  assert.equal(out.length, 1);
});

test('phone format variants merge', () => {
  const out = dedupeCustomers([
    { name: 'A', email: 'a1@x.com', phone: '(415) 555-0132' },
    { name: 'A', email: 'a2@x.com', phone: '415.555.0132' },
    { name: 'A', email: 'a3@x.com', phone: '+1 415 555 0132 ' },
    { name: 'A', email: 'a4@x.com', phone: '1-415-555-0132' },
  ]);
  assert.equal(out.length, 1);
});

test('chained matches collapse into one group', () => {
  const out = dedupeCustomers([
    { name: 'J. Okafor', email: 'jo@x.com', phone: '415-555-0100' },
    { name: 'Jide Okafor', email: 'JO@x.com', phone: '(212) 555-0111' },
    { name: 'Jide O.', email: 'jide@work.com', phone: '212 555 0111' },
  ]);
  assert.equal(out.length, 1);
});

test('blank email/phone never match each other', () => {
  const out = dedupeCustomers([
    { name: 'Ann', email: '', phone: '' },
    { name: 'Bob', email: '   ', phone: null },
    { name: 'Cy', phone: undefined },
  ]);
  assert.equal(out.length, 3);
});

test('distinct customers stay separate, in order', () => {
  const input = [
    { name: 'Lena', email: 'lena@x.com', phone: '415-555-0101' },
    { name: 'Marco', email: 'marco@x.com', phone: '415-555-0102' },
    { name: 'Lena', email: 'lena@y.com', phone: '415-555-0103' }, // same name only
  ];
  assert.deepEqual(dedupeCustomers(input).map((r) => r.email), input.map((r) => r.email));
});

test('keeps most complete record, fills blanks, preserves first-appearance order', () => {
  const out = dedupeCustomers([
    { name: 'Zed', email: 'zed@x.com', phone: '' },
    { name: 'Kim', email: 'kim@x.com', phone: '415-555-0199' },
    { name: '', email: 'ZED@x.com', phone: '415-555-0150' },
  ]);
  assert.deepEqual(out, [
    { name: 'Zed', email: 'zed@x.com', phone: '415-555-0150' },
    { name: 'Kim', email: 'kim@x.com', phone: '415-555-0199' },
  ]);
});

test('does not mutate input', () => {
  const input = [
    { name: 'A', email: ' A@x.com ', phone: '' },
    { name: '', email: 'a@x.com', phone: '415-555-0132' },
  ];
  const snapshot = JSON.parse(JSON.stringify(input));
  const out = dedupeCustomers(input);
  assert.deepEqual(input, snapshot);
  assert.notEqual(out[0], input[0]);
});
